CREATE TABLE projected_work_topic WITH (format='PARQUET',write_compression='ZSTD') AS SELECT try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS work_id,try_cast(regexp_extract(t.id, '[A-Z]([0-9]+)$', 1) AS bigint) AS topic_id,cast(t.score AS real) AS score,coalesce(try_cast(regexp_extract(t.id, '[A-Z]([0-9]+)$', 1) AS bigint)=try_cast(regexp_extract(w.primary_topic.id, '[A-Z]([0-9]+)$', 1) AS bigint),false) AS is_primary FROM raw_works w CROSS JOIN UNNEST(w.topics) AS u(t) WHERE try_cast(regexp_extract(w.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND try_cast(regexp_extract(t.id, '[A-Z]([0-9]+)$', 1) AS bigint) IS NOT NULL AND t.score IS NOT NULL;
